def point_type(name, fields, srid_map):
    """Dynamically create a Point subclass."""
    # Create a base class with the given name and srid mapping
    class _BasePoint(Point):
        __slots__ = ('srid',)

        def __init__(self, *args, **kwargs):
            self.srid = srid_map.get(args[0], kwargs.get("srid", None))

        @property
        def x(self):
            return self.srid

        @x.setter
        def x(self, val):
            raise TypeError("read-only property")

        @property
        def y(self):
            return self.srid

        @y.setter
        def y(self, val):
            raise TypeError("read-only property")

        @property
        def z(self):
            return self.srid

        @z.setter
        def z(self, val):
            raise TypeError("read-only property")

    # Create a subclass with the given name and inherited fields
    class Point(name, _BasePoint):
        __slots__ = ()

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)

        # Add the extra fields to the class
        for field in fields:
            if field not in ["x", "y", "z"]:
                setattr(cls, field, property(lambda self, f=field: self.srid[f],
                                                    lambda self, v, f=field: self.srid[f] = v))

    return Point

def deprecated(message):
    """
    Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    def deprecated_function(func):
        def wrapper(*args, **kwargs):
            warnings.warn("Deprecated function '{}'.".format(func.__name__),
                          FutureWarning)
            return func(*args, **kwargs)
        return wrapper
    return deprecated_function(message)

