def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version and 'type' in inventory:
        # Infer the specification version from the type value
        spec_version = inventory['type']
        if spec_version in self.SUPPORTED_VERSIONS:
            # Use the specified version for validation
            self.spec_version = spec_version

    # Validate the inventory based on the specified specification version
    for item in inventory:
        if item['type'] not in self.SUPPORTED_TYPES:
            raise SchemaFormatException('Unsupported type: {}'.format(item['type']))

        if item['type'] == 'string':
            if len(item['value']) > 50:
                raise SchemaFormatException('String value exceeds 50 characters')

        elif item['type'] == 'object':
            if 'description' not in item:
                raise SchemaFormatException('Object type must have a description')

            if len(item['description']) > 256:
                raise SchemaFormatException('Description exceeds 256 characters')

            if not all(isinstance(i, list) for i in item['attributes']):
                raise SchemaFormatException('Attributes must be a list')

            for attr in item['attributes']:
                if len(attr) != 2:
                    raise SchemaFormatException('Attributes must have two items')

                if len(attr[0]) > 20:
                    raise SchemaFormatException('Attribute key longer than 20 characters')

                if len(attr[1]) > 50:
                    raise SchemaFormatException('Attribute value longer than 50 characters')

    return inventory

