def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an instance of InventoryValidator")

    if self.num_items != prior.num_items:
        raise ValueError("Incompatible inventories: number of items differ")

    if self.num_locations != prior.num_locations:
        raise ValueError("Incompatible inventories: number of locations differ")

    if self.num_demands != prior.num_demands:
        raise ValueError("Incompatible inventories: number of demands differ")

    if self.item_capacities != prior.item_capacities:
        raise ValueError("Incompatible inventories: item capacities differ")

    if self.location_capacities != prior.location_capacities:
        raise ValueError("Incompatible inventories: location capacities differ")

    if self.item_demands != prior.item_demands:
        raise ValueError("Incompatible inventories: item demands differ")

    if self.location_locations != prior.location_locations:
        raise ValueError("Incompatible inventories: location locations differ")

    if self.item_locations != prior.item_locations:
        raise ValueError("Incompatible inventories: item locations differ")

    if self.demand_locations != prior.demand_locations:
        raise ValueError("Incompatible inventories: demand locations differ")

    if self.item_probs != prior.item_probs:
        raise ValueError("Incompatible inventories: item probabilities differ")

    if self.location_probs != prior.location_probs:
        raise ValueError("Incompatible inventories: location probabilities differ")

    if self.demand_probs != prior.demand_probs:
        raise ValueError("Incompatible inventories: demand probabilities differ")

    if self.item_crafting_times != prior.item_crafting_times:
        raise ValueError("Incompatible inventories: item crafting times differ")

    if self.location_storage_times != prior.location_storage_times:
        raise ValueError("Incompatible inventories: location storage times differ")

    if self.demand_storage_times != prior.demand_storage_times:
        raise ValueError("Incompatible inventories: demand storage times differ")

    # Check that the inventory object satisfies the validity conditions for each item, location, and demand
    for i in range(self.num_items):
        for l in range(self.num_locations):
            for d in range(self.num_demands):
                if self.item_capacities[i, l] < self.location_capacities[l]:
                    raise ValueError("Inventory does not satisfy the validity conditions for item {0} and location {1}".format(i, l))

                if self.item_demands[i, l] > self.demand_locations[d, l]:
                    raise ValueError("Inventory does not satisfy the validity conditions for item {0} and demand {1}".format(i, d))

                if self.item_probs[i] < self.location_probs[l] or self.item_probs[i] > self.demand_probs[d]:
                    raise ValueError("Inventory does not satisfy the validity conditions for item {0}".format(i))

                if self.item_crafting_times[i, l] > self.location_storage_times[l]:
                    raise ValueError("Inventory does not satisfy the validity conditions for item {0} and location {1}".format(i, l))

                if self.item_demands[i, l] > self.demand_locations[d, l] or self.item_crafting_times[i, l] > self.demand_storage_times[d]:
                    raise ValueError("Inventory does not satisfy the validity conditions for item {0} and demand {1}".format(i, d))

    # Check that the demand objects satisfy the validity conditions for each demand
    for d in range(self.num_demands):
        if self.demand_probs[d] == 0:
            raise ValueError("Demand {0} has a zero probability".format(d))

        if self.demand_locations[d, 0] == 0:
            raise ValueError("Demand {0} has a zero location set".format(d))

        if self.demand_storage_times[d] < np.sum(self.item_crafting_times[self.item_demands[self.demand_locations[d, :], np.newaxis], self.location_locations[self.demand_locations[d, 0], np.newaxis]]):
            raise ValueError("Inventory does not satisfy the validity conditions for demand {0}".format(d))

    # Check that the item objects satisfy the validity conditions for each item
    for i in range(self.num_items):
        if self.item_probs[i] == 0:
            raise ValueError("Item {0} has a zero probability".format(i))

        if self.item_locations[i, 0] == 0:
            raise ValueError("Item {0} has a zero location set".format(i))

        if self.item_crafting_times[i, 0] < np.sum(self.location_storage_times[self.item_locations[i, :]]):
            raise ValueError("Inventory does not satisfy the validity conditions for item {0}".format(i))

def get_logical_path_map(inventory, version):
    """
    Returns a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """

    content_files = {}

    for entry in inventory.get_entries(version):
        if not entry.has_logical_path:
            continue

        logical_path = entry.logical_path
        if logical_path in content_files:
            content_files[logical_path].add(entry.path)
        else:
            content_files[logical_path] = {entry.path}

    return content_files

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")
    if not isinstance(manifest_files, list):
        raise ValueError("Manifest files must be a list")

    for file in manifest_files:
        if file not in fixity:
            raise ValueError(f"{file} is not in the fixity block")
        hash_type, expected_hash = fixity[file].split("-", 1)
        if not hash_type or not expected_hash:
            raise ValueError(f"Invalid hash type and expected hash for {file}")

    for file in fixity.keys():
        if file not in manifest_files:
            raise ValueError(f"{file} is not in the manifest")
        if not fixity[file].endswith("-" + expected_hash):
            raise ValueError(f"File {file} has an invalid hash")

    return True

