def run_command(commands: list, args: list, cwd: str = None, verbose: bool = False, hide_stderr: bool = False, env: dict = None):
    """
    Call the given command(s).

    :param commands: list of commands to run
    :param args: list of command-line arguments to pass to the command
    :param cwd: current working directory for the command
    :param verbose: whether to display the command and its output
    :param hide_stderr: whether to hide stderr output
    :param env: environment variables to set for the command

    :return: boolean indicating if the command succeeded
    """
    if not commands:
        raise ValueError("No commands to execute")

    cmd = commands[0]
    if env:
        env = os.environ.copy()
        env.update(env)

    if cwd:
        cwd = cwd
    else:
        cwd = os.getcwd()

    if not verbose:
        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = subprocess.PIPE

    try:
        output = subprocess.check_output(cmd + args, shell=False, stderr=stderr, cwd=cwd, env=env)
    except subprocess.CalledProcessError as error:
        success = False
    else:
        success = True

    if verbose:
        if hide_stderr or not output:
            print(" ".join(cmd + args))
        else:
            print(" ".join(cmd + args))
            print(output.decode("utf-8"))

    return success

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
