def deep_merge_nodes(nodes):
    result = {}
    for key, value in nodes:
        current_value = result.get(key)
        if current_value is None:
            if isinstance(value, ruamel.yaml.nodes.MappingNode):
                result[key] = value
            else:
                result[key] = current_value
        elif isinstance(value, ruamel.yaml.nodes.MappingNode):
            if not isinstance(current_value, ruamel.yaml.nodes.MappingNode):
                result[key] = value
            else:
                for subkey, subvalue in value.value:
                    current_subkey = current_value.value(subkey)
                    if current_subkey is None:
                        result.setdefault(subkey, subvalue)
                    elif isinstance(current_subkey, ruamel.yaml.nodes.MappingNode):
                        result[subkey] = deep_merge_nodes([
                            (current_subkey.key, current_subkey.value),
                            (subkey, subvalue),
                        ])
                    else:
                        result[subkey] = subvalue
    return result

