def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()

    queue = set([cls])
    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for sc in sc:
            if not (sc in seen or sc in queue):
                queue.add(sc)
    seen.remove(cls)
    return seen

