def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    if frequency.isdigit():
        factor, unit = frequency, "weeks"
    else:
        match = re.fullmatch(r"(\d+)\s*([^\r\n\d\W]+)", frequency)
        if not match:
            raise ValueError(f"Invalid frequency: {frequency!r}")
        factor = int(match.group(1))
        unit = match.group(2)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=factor)
    elif unit in ("day", "days"):
        return datetime.timedelta(days=factor)
    elif unit in ("hour", "hours"):
        return datetime.timedelta(hours=factor)
    elif unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=factor)
    else:
        raise ValueError(f"Invalid frequency unit: {unit!r}")

