def protocol_handlers(protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
    If an explicit protocol version is provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """

    # Handle no protocol version provided case
    if not protocol_version:
        return {(3, 0): Bolt3Handler}

    # Check if the protocol version is a tuple
    if not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be a tuple of two integers")

    # Check if the protocol version is supported
    if protocol_version == (3, 0):
        return {(3, 0): Bolt3Handler}
    elif protocol_version == (3, 1):
        return {(3, 1): Bolt3Handler}
    elif protocol_version == (3, 2):
        return {(3, 2): Bolt3Handler}
    else:
        return {}

