    """

    # Check if the Content-Type header is application/x-www-form-urlencoded
    if request.headers.get('Content-Type', '').startswith('application/x-www-form-urlencoded'):
        return True

    # Check if the POST body is a JSON encoded object
    try:
        json.loads(request.body)
    except ValueError:
        return False

    # Check if the object contains a "type" key with the value "m.room.message"
    if 'type' in request.body and request.body['type'] == 'm.room.message':
        return True

    return False

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    new_text = ''
    for line in text.split('\n'):
        if line.startswith("#"):
            tag_word = line.lstrip("# ").strip()
            if replacer is not None:
                new_line = replacer(tag_word)
                new_text += f"#{new_line}"
            else:
                new_text += line
            tags.add(tag_word)
        else:
            new_text += line + '\n'
    return tags, new_text

