    for arg in answer_file_args:
        if arg in cli_args:
            print(f"WARNING: The answer file argument {arg} is deprecated and will be ignored. Please use {cli_args[arg]} instead.")
    # filter out deprecated args
    cli_args = {key: value for key, value in cli_args.items() if key not in answer_file_args}
    answer_file_args = {key: value for key, value in answer_file_args.items() if key not in cli_args}
    return cli_args, answer_file_args

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    option_specs = []
    for command in self.commands:
        if command.name == command_name:
            for option in command.options:
                option_specs.append(option.spec)
    return option_specs

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    required_args = {arg for arg in self.args if arg.required}
    provided_args = {arg for arg in args if arg in self.args}
    return required_args.issubset(provided_args)

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.max_length:
            raise ValueError(f"Argument '{arg}' is too long, maximum length is {self.max_length}")

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.available_choices:
            message = f"Value for argument {arg} must be one of the following: {self.available_choices}"
            raise ValueError(message)

def validate_min_max_args(self, args):
    """
    Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    for arg in args:
        if arg < arg.minimum or arg > arg.maximum:
            raise ValueError("Argument value is out of range.")
    return args

def get_nested_custom_and_control_args(args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('-'):
            if arg in CONTROL_ARGS:
                control_args[arg] = args[arg]
            elif arg.startswith(CUSTOM_ARGS_PREFIX):
                custom_args[arg[1:]] = args[arg]
        else:
            # assume it is a nested arg
            nested_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def _convert_non_cli_args(self, parser_name, values_dict):
    arg_parsers = {
        "main": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
        "virsh": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
        "ospd": {
            "--max-memory": int,
            "--max-time": int,
            "--max-restarts": int
        },
    }

    if parser_name not in arg_parsers:
        raise ValueError(f"Unsupported parser name: {parser_name}")

    for arg, expected_type in arg_parsers[parser_name].items():
        value = values_dict.get(arg)
        if value is None:
            continue

        try:
            values_dict[arg] = expected_type(value)
        except ValueError:
            raise ValueError(f"{arg} must be of type {expected_type}, but given value is {value}")

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    with open(os.path.join(plugin_dir, 'plugin_spec.json')) as f:
        plugin_spec = json.load(f)

    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, list):
            for item in value:
                flatten_dict[key + '/' + item] = True
        else:
            flatten_dict[key] = value

    return flatten_dict

def inject_config(self):
    if os.getenv('CONFIG_PATH') is None:
        os.environ['CONFIG_PATH'] = str(self.config_path)

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("path is not under root")
    return path[len(root):]
